/**
 * Tests for useAutoSnapshot Hook
 *
 * Tests both trigger modes:
 * - character_count: snapshot when content increases by threshold
 * - on_leave: snapshot on component unmount
 */

import { invoke } from '@tauri-apps/api/core';
import { renderHook } from '@testing-library/react';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { mockTauriInvoke, resetTauriMocks } from '@/test/utils';
import { useAutoSnapshot } from './useAutoSnapshot';

const mockInvoke = invoke as ReturnType<typeof vi.fn>;

describe('useAutoSnapshot', () => {
  beforeEach(() => {
    resetTauriMocks();
    mockTauriInvoke('create_story_snapshot', {
      id: 'snapshot-1',
      versionId: 'version-1',
      content: '',
      createdAt: '',
    });
  });

  describe('Character Count Trigger', () => {
    it('does not create snapshot on initial render', () => {
      renderHook(() =>
        useAutoSnapshot({
          storyId: 'story-1',
          content: 'Initial content',
          enabled: true,
          trigger: 'character_count',
          characterThreshold: 500,
        }),
      );

      expect(mockInvoke).not.toHaveBeenCalled();
    });

    it('creates snapshot when content increases by threshold', async () => {
      const { rerender } = renderHook(
        ({ content }) =>
          useAutoSnapshot({
            storyId: 'story-1',
            content,
            enabled: true,
            trigger: 'character_count',
            characterThreshold: 10,
          }),
        { initialProps: { content: 'Initial' } },
      );

      // Add content that exceeds threshold (10 chars)
      rerender({ content: 'Initial content that is longer than before' });

      await vi.waitFor(() => {
        expect(mockInvoke).toHaveBeenCalledWith('create_story_snapshot', {
          storyId: 'story-1',
          content: 'Initial content that is longer than before',
        });
      });
    });

    it('does not create snapshot when content increases below threshold', () => {
      const { rerender } = renderHook(
        ({ content }) =>
          useAutoSnapshot({
            storyId: 'story-1',
            content,
            enabled: true,
            trigger: 'character_count',
            characterThreshold: 100,
          }),
        { initialProps: { content: 'Initial' } },
      );

      // Add only 5 characters (below threshold of 100)
      rerender({ content: 'Initial text' });

      expect(mockInvoke).not.toHaveBeenCalled();
    });

    it('does not create snapshot when content decreases (deletion)', () => {
      const { rerender } = renderHook(
        ({ content }) =>
          useAutoSnapshot({
            storyId: 'story-1',
            content,
            enabled: true,
            trigger: 'character_count',
            characterThreshold: 10,
          }),
        { initialProps: { content: 'This is some initial content' } },
      );

      // Delete content (should NOT trigger snapshot)
      rerender({ content: 'Short' });

      expect(mockInvoke).not.toHaveBeenCalled();
    });

    it('tracks character count from last snapshot', async () => {
      const { rerender } = renderHook(
        ({ content }) =>
          useAutoSnapshot({
            storyId: 'story-1',
            content,
            enabled: true,
            trigger: 'character_count',
            characterThreshold: 10,
          }),
        { initialProps: { content: 'Start' } }, // 5 chars
      );

      // First increase: 5 -> 19 chars (delta = 14, exceeds threshold of 10)
      rerender({ content: 'Start and more text' }); // 19 chars

      // Wait for the async snapshot to be called AND the promise chain to complete
      await vi.waitFor(() => {
        expect(mockInvoke).toHaveBeenCalledTimes(1);
      });

      // Allow microtasks to complete (the .then() that updates lastSnapshotCharCount)
      await new Promise((resolve) => setTimeout(resolve, 10));

      // Small increase from 19 -> 21 (delta = 2, below threshold)
      // This should NOT trigger because we're measuring from last snapshot
      mockInvoke.mockClear();
      rerender({ content: 'Start and more text!!' }); // 21 chars, delta from 19 = 2

      // Give the effect a chance to run
      await new Promise((resolve) => setTimeout(resolve, 10));
      expect(mockInvoke).not.toHaveBeenCalled();

      // Large increase from 21 -> 34 (delta = 13, exceeds threshold)
      rerender({ content: 'Start and more text plus even more' }); // 34 chars

      await vi.waitFor(() => {
        expect(mockInvoke).toHaveBeenCalledTimes(1);
      });
    });

    it('does not create snapshot when disabled', () => {
      const { rerender } = renderHook(
        ({ content, enabled }) =>
          useAutoSnapshot({
            storyId: 'story-1',
            content,
            enabled,
            trigger: 'character_count',
            characterThreshold: 10,
          }),
        { initialProps: { content: 'Initial', enabled: false } },
      );

      // Add content that would exceed threshold
      rerender({ content: 'Initial content that is much longer now', enabled: false });

      expect(mockInvoke).not.toHaveBeenCalled();
    });

    it('uses default threshold of 500 when not specified', () => {
      const { rerender } = renderHook(
        ({ content }) =>
          useAutoSnapshot({
            storyId: 'story-1',
            content,
            enabled: true,
            trigger: 'character_count',
            // characterThreshold not specified, should default to 500
          }),
        { initialProps: { content: 'Start' } },
      );

      // Add 100 characters (below default threshold of 500)
      const shortAddition = 'a'.repeat(100);
      rerender({ content: `Start${shortAddition}` });
      expect(mockInvoke).not.toHaveBeenCalled();

      // Add 500+ characters (exceeds default threshold)
      const longAddition = 'b'.repeat(500);
      rerender({ content: `Start${shortAddition}${longAddition}` });
      expect(mockInvoke).toHaveBeenCalled();
    });
  });

  describe('On-Leave Trigger', () => {
    it('creates snapshot on unmount when trigger is on_leave', () => {
      const { unmount } = renderHook(() =>
        useAutoSnapshot({
          storyId: 'story-1',
          content: 'Some content to save',
          enabled: true,
          trigger: 'on_leave',
          characterThreshold: 500,
        }),
      );

      expect(mockInvoke).not.toHaveBeenCalled();

      // Unmount the component
      unmount();

      expect(mockInvoke).toHaveBeenCalledWith('create_story_snapshot', {
        storyId: 'story-1',
        content: 'Some content to save',
      });
    });

    it('creates snapshot on unmount with character_count trigger when content changed', () => {
      const { rerender, unmount } = renderHook(
        ({ content }) =>
          useAutoSnapshot({
            storyId: 'story-1',
            content,
            enabled: true,
            trigger: 'character_count',
            characterThreshold: 1000, // High threshold so it won't trigger during typing
          }),
        { initialProps: { content: 'Initial' } },
      );

      // Change content but not enough to trigger threshold
      rerender({ content: 'Initial modified' });
      expect(mockInvoke).not.toHaveBeenCalled();

      // Unmount - should still create snapshot because content changed
      unmount();

      expect(mockInvoke).toHaveBeenCalledWith('create_story_snapshot', {
        storyId: 'story-1',
        content: 'Initial modified',
      });
    });

    it('does not create snapshot on unmount when disabled', () => {
      const { unmount } = renderHook(() =>
        useAutoSnapshot({
          storyId: 'story-1',
          content: 'Some content',
          enabled: false,
          trigger: 'on_leave',
          characterThreshold: 500,
        }),
      );

      unmount();

      expect(mockInvoke).not.toHaveBeenCalled();
    });

    it('does not create snapshot on unmount when no changes', () => {
      const { unmount } = renderHook(() =>
        useAutoSnapshot({
          storyId: 'story-1',
          content: 'Same content',
          enabled: true,
          trigger: 'character_count', // Not on_leave
          characterThreshold: 500,
        }),
      );

      // Content hasn't changed from initial, and trigger is not on_leave
      // Since lastSnapshotCharCount equals content.length, no snapshot should be created
      unmount();

      expect(mockInvoke).not.toHaveBeenCalled();
    });
  });

  describe('Story ID Changes', () => {
    it('resets tracking when storyId changes', async () => {
      const { rerender } = renderHook(
        ({ storyId, content }) =>
          useAutoSnapshot({
            storyId,
            content,
            enabled: true,
            trigger: 'character_count',
            characterThreshold: 10,
          }),
        { initialProps: { storyId: 'story-1', content: 'Initial content for story 1' } },
      );

      // Change to a different story
      rerender({ storyId: 'story-2', content: 'New story content' });

      // Small change after story switch should not trigger because it is below threshold.
      mockInvoke.mockClear();
      rerender({ storyId: 'story-2', content: 'New story content!' });

      expect(mockInvoke).not.toHaveBeenCalled();

      // A larger follow-up change should use the new story baseline.
      rerender({ storyId: 'story-2', content: 'New story content with more and even more text' });

      await vi.waitFor(() => {
        expect(mockInvoke).toHaveBeenCalledWith('create_story_snapshot', {
          storyId: 'story-2',
          content: 'New story content with more and even more text',
        });
      });
    });

    it('rebases the baseline when content loads after tracking is enabled', async () => {
      const { rerender } = renderHook(
        ({ content, enabled }) =>
          useAutoSnapshot({
            storyId: 'story-1',
            content,
            enabled,
            trigger: 'character_count',
            characterThreshold: 10,
          }),
        { initialProps: { content: '', enabled: false } },
      );

      rerender({ content: 'Existing story body', enabled: true });
      expect(mockInvoke).not.toHaveBeenCalled();

      rerender({ content: 'Existing story body!', enabled: true });
      expect(mockInvoke).not.toHaveBeenCalled();

      rerender({ content: 'Existing story body with enough extra text', enabled: true });

      await vi.waitFor(() => {
        expect(mockInvoke).toHaveBeenCalledWith('create_story_snapshot', {
          storyId: 'story-1',
          content: 'Existing story body with enough extra text',
        });
      });
    });
  });

  describe('Error Handling', () => {
    it('logs error when snapshot creation fails', async () => {
      const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
      mockInvoke.mockRejectedValueOnce(new Error('Database error'));

      const { rerender } = renderHook(
        ({ content }) =>
          useAutoSnapshot({
            storyId: 'story-1',
            content,
            enabled: true,
            trigger: 'character_count',
            characterThreshold: 10,
          }),
        { initialProps: { content: 'Initial' } },
      );

      rerender({ content: 'Initial with lots more content added' });

      await vi.waitFor(
        () => {
          expect(consoleSpy).toHaveBeenCalledWith('Auto-snapshot error:', expect.any(Error));
        },
        { timeout: 1000 },
      );

      consoleSpy.mockRestore();
    });

    it('logs error when cleanup snapshot fails', async () => {
      const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
      mockInvoke.mockRejectedValueOnce(new Error('Cleanup error'));

      const { unmount } = renderHook(() =>
        useAutoSnapshot({
          storyId: 'story-1',
          content: 'Content to save',
          enabled: true,
          trigger: 'on_leave',
          characterThreshold: 500,
        }),
      );

      unmount();

      await vi.waitFor(() => {
        expect(consoleSpy).toHaveBeenCalledWith('Auto-snapshot cleanup error:', expect.any(Error));
      });

      consoleSpy.mockRestore();
    });
  });

  describe('Trigger Mode Switching', () => {
    it('respects trigger mode changes', () => {
      type TriggerProps = { trigger: 'on_leave' | 'character_count'; content: string };
      const { rerender } = renderHook<void, TriggerProps>(
        ({ trigger, content }) =>
          useAutoSnapshot({
            storyId: 'story-1',
            content,
            enabled: true,
            trigger,
            characterThreshold: 10,
          }),
        { initialProps: { trigger: 'on_leave', content: 'Initial' } },
      );

      // With on_leave trigger, content changes should not trigger snapshots
      rerender({ trigger: 'on_leave', content: 'Initial with a lot more content now' });
      expect(mockInvoke).not.toHaveBeenCalled();

      // Switch to character_count trigger
      rerender({ trigger: 'character_count', content: 'Initial with a lot more content now' });

      // Now content changes should trigger (but this render is treated as "initial" for the new trigger)
      // Add more content to trigger
      rerender({
        trigger: 'character_count',
        content: 'Initial with a lot more content now and even more',
      });
      expect(mockInvoke).toHaveBeenCalled();
    });
  });
});

/**
 * useAutoSnapshot Hook
 *
 * Custom React hook for creating automatic history restore points (snapshots)
 * based on character count threshold or component unmount (on-leave) trigger.
 *
 * Part of Database-Only Versioning (DBV) implementation.
 */

import { useCallback, useEffect, useRef } from 'react';
import type { SnapshotTrigger } from '@/features/settings/stores/useSettingsStore';
import { createStorySnapshot } from '@/features/stories/api/snapshots';

export interface UseAutoSnapshotProps {
  /** The story ID to create snapshots for */
  storyId: string;
  /** The current content to snapshot */
  content: string;
  /** Current word count for the editor content */
  wordCount?: number;
  /** Whether auto-snapshot is enabled */
  enabled: boolean;
  /** Trigger mode: 'on_leave' or 'character_count' */
  trigger: SnapshotTrigger;
  /** Character count threshold for 'character_count' trigger (default: 500) */
  characterThreshold?: number;
  /** Maximum snapshots to keep for the current version */
  maxSnapshots?: number;
}

/**
 * useAutoSnapshot Hook
 *
 * Creates automatic snapshots based on the configured trigger mode:
 * - 'character_count': Creates a snapshot when the content length increases by the threshold
 * - 'on_leave': Creates a snapshot when the component unmounts
 *
 * Key behaviors:
 * - Only triggers on content INCREASE (deletions don't create snapshots)
 * - Handles initial load correctly (no immediate snapshot)
 * - Tracks last snapshot character count to avoid duplicates
 *
 * @example
 * ```tsx
 * useAutoSnapshot({
 *   storyId: story.id,
 *   content: editorContent,
 *   enabled: true,
 *   trigger: 'character_count',
 *   characterThreshold: 500,
 * });
 * ```
 */
export function useAutoSnapshot({
  storyId,
  content,
  wordCount,
  enabled,
  trigger,
  characterThreshold = 500,
  maxSnapshots,
}: UseAutoSnapshotProps): void {
  // Track the character count and content at the time of last snapshot
  const lastSnapshotCharCount = useRef(0);
  const lastSnapshotContentRef = useRef(content);
  const hasInitializedBaseline = useRef(false);
  const previousEnabledRef = useRef(enabled);
  const previousStoryIdRef = useRef(storyId);

  // Store latest values in refs to avoid stale closures in cleanup
  const storyIdRef = useRef(storyId);
  const contentRef = useRef(content);
  const wordCountRef = useRef(wordCount);
  const enabledRef = useRef(enabled);
  const triggerRef = useRef(trigger);
  const maxSnapshotsRef = useRef(maxSnapshots);

  // Update refs when values change
  storyIdRef.current = storyId;
  contentRef.current = content;
  wordCountRef.current = wordCount;
  enabledRef.current = enabled;
  triggerRef.current = trigger;
  maxSnapshotsRef.current = maxSnapshots;

  // Create snapshot function
  const createSnapshot = useCallback(
    async (
      snapshotContent: string,
      snapshotStoryId: string,
      snapshotWordCount?: number,
      snapshotMaxSnapshots?: number,
    ) => {
      try {
        await createStorySnapshot({
          storyId: snapshotStoryId,
          content: snapshotContent,
          wordCount: snapshotWordCount,
          maxSnapshots: snapshotMaxSnapshots,
        });
      } catch (error) {
        console.error('Auto-snapshot error:', error);
      }
    },
    [],
  );

  // Rebase the snapshot baseline when a story finishes loading or tracking is re-enabled.
  useEffect(() => {
    const storyChanged = previousStoryIdRef.current !== storyId;
    const enabledChanged = previousEnabledRef.current !== enabled;

    previousStoryIdRef.current = storyId;
    previousEnabledRef.current = enabled;

    if (!enabled) {
      hasInitializedBaseline.current = false;
      lastSnapshotCharCount.current = content.length;
      lastSnapshotContentRef.current = content;
      return;
    }

    if (storyChanged || enabledChanged || !hasInitializedBaseline.current) {
      lastSnapshotCharCount.current = content.length;
      lastSnapshotContentRef.current = content;
      hasInitializedBaseline.current = true;
    }
  }, [storyId, content, enabled]);

  // Character count trigger: create snapshot when chars increase by threshold
  useEffect(() => {
    // Skip if disabled or not using character_count trigger
    if (!enabled || trigger !== 'character_count' || !hasInitializedBaseline.current) {
      return;
    }

    // Calculate the character difference from last snapshot
    const charsDelta = content.length - lastSnapshotCharCount.current;

    // Only trigger on content INCREASE (positive delta) meeting threshold
    if (charsDelta >= characterThreshold) {
      createSnapshot(content, storyId, wordCount, maxSnapshots).then(() => {
        lastSnapshotCharCount.current = content.length;
        lastSnapshotContentRef.current = content;
      });
    }
  }, [
    content,
    storyId,
    enabled,
    trigger,
    characterThreshold,
    wordCount,
    maxSnapshots,
    createSnapshot,
  ]);

  // On-leave trigger: create snapshot on component unmount
  useEffect(() => {
    // Return cleanup function for unmount
    return () => {
      // Check enabled state from ref (latest value)
      if (!enabledRef.current) {
        return;
      }

      // Determine if we should snapshot on unmount
      const shouldSnapshot =
        triggerRef.current === 'on_leave' ||
        // Also snapshot if there are unsaved changes (content changed since last snapshot)
        contentRef.current !== lastSnapshotContentRef.current;

      if (shouldSnapshot) {
        createStorySnapshot({
          storyId: storyIdRef.current,
          content: contentRef.current,
          wordCount: wordCountRef.current,
          maxSnapshots: maxSnapshotsRef.current,
        }).catch((error) => {
          console.error('Auto-snapshot cleanup error:', error);
        });
      }
    };
  }, []); // Empty deps - cleanup only runs on unmount
}

