/**
 * Rich Text Editor Component
 *
 * A Lexical-based rich text editor with basic formatting capabilities.
 * Supports bold, italic, underline, headings, and lists.
 */

import { LinkNode } from '@lexical/link';
import { ListItemNode, ListNode } from '@lexical/list';
import { LexicalComposer } from '@lexical/react/LexicalComposer';
import { ContentEditable } from '@lexical/react/LexicalContentEditable';
import { HistoryPlugin } from '@lexical/react/LexicalHistoryPlugin';
import { RichTextPlugin } from '@lexical/react/LexicalRichTextPlugin';
import { HeadingNode, QuoteNode } from '@lexical/rich-text';
import type { EditorState } from 'lexical';
import { useState } from 'react';
import { ContentChangePlugin } from './plugins/ContentChangePlugin';
import { ToolbarPlugin } from './plugins/ToolbarPlugin';
import './RichTextEditor.css';

export interface RichTextEditorProps {
  /** Initial content as JSON string (Lexical EditorState) */
  initialContent?: string;
  /** Callback when content changes */
  onChange?: (content: string) => void;
  /** Whether the editor is read-only */
  readOnly?: boolean;
  /** Placeholder text when editor is empty */
  placeholder?: string;
}

/**
 * RichTextEditor Component
 */
export function RichTextEditor({
  initialContent,
  onChange,
  readOnly = false,
  placeholder = 'Start writing...',
}: RichTextEditorProps) {
  // Store the initial content only once when the component first mounts
  // This prevents the editor from remounting on every keystroke
  const [initialEditorState] = useState(() => initialContent || null);
  const editorKey = readOnly ? 'read-only' : 'editable';

  const initialConfig = {
    namespace: 'RichTextEditor',
    theme: {
      paragraph: 'editor-paragraph',
      text: {
        bold: 'editor-text-bold',
        italic: 'editor-text-italic',
        underline: 'editor-text-underline',
      },
      heading: {
        h1: 'editor-heading-h1',
        h2: 'editor-heading-h2',
        h3: 'editor-heading-h3',
      },
      list: {
        ul: 'editor-list-ul',
        ol: 'editor-list-ol',
        listitem: 'editor-listitem',
      },
      quote: 'editor-quote',
    },
    nodes: [HeadingNode, QuoteNode, ListNode, ListItemNode, LinkNode],
    editable: !readOnly,
    editorState: initialEditorState,
    onError: (error: Error) => {
      console.error('Lexical Editor Error:', error);
    },
  };

  const handleChange = (editorState: EditorState) => {
    if (onChange && !readOnly) {
      const json = JSON.stringify(editorState.toJSON());
      onChange(json);
    }
  };

  return (
    <div className={`rich-text-editor ${readOnly ? 'read-only' : ''}`}>
      <LexicalComposer key={editorKey} initialConfig={initialConfig}>
        {!readOnly && <ToolbarPlugin />}
        <div className="editor-container">
          <RichTextPlugin
            contentEditable={
              <ContentEditable
                className="editor-content"
                aria-placeholder={placeholder}
                placeholder={<div className="editor-placeholder">{placeholder}</div>}
              />
            }
            ErrorBoundary={() => <div>Error loading editor</div>}
          />
          <HistoryPlugin />
          <ContentChangePlugin onChange={handleChange} />
        </div>
      </LexicalComposer>
    </div>
  );
}

/**
 * Toolbar Plugin
 *
 * Provides formatting toolbar for the Lexical editor.
 * Supports bold, italic, underline, headings, and lists.
 */

import {
  $isListNode,
  INSERT_ORDERED_LIST_COMMAND,
  INSERT_UNORDERED_LIST_COMMAND,
  REMOVE_LIST_COMMAND,
} from '@lexical/list';
import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { $createHeadingNode, $isHeadingNode, type HeadingTagType } from '@lexical/rich-text';
import { $setBlocksType } from '@lexical/selection';
import { mergeRegister } from '@lexical/utils';
import {
  ListBullets,
  ListNumbers,
  TextB,
  TextHOne,
  TextHTwo,
  TextItalic,
  TextUnderline,
} from '@phosphor-icons/react';
import {
  $createParagraphNode,
  $getSelection,
  $isRangeSelection,
  FORMAT_TEXT_COMMAND,
  SELECTION_CHANGE_COMMAND,
} from 'lexical';
import { useCallback, useEffect, useState } from 'react';

type ToolbarBlockType = 'paragraph' | HeadingTagType | 'ul' | 'ol';

export function ToolbarPlugin() {
  const [editor] = useLexicalComposerContext();
  const [isBold, setIsBold] = useState(false);
  const [isItalic, setIsItalic] = useState(false);
  const [isUnderline, setIsUnderline] = useState(false);
  const [blockType, setBlockType] = useState<ToolbarBlockType>('paragraph');

  const updateToolbar = useCallback(() => {
    const selection = $getSelection();
    if ($isRangeSelection(selection)) {
      // Update text format states
      setIsBold(selection.hasFormat('bold'));
      setIsItalic(selection.hasFormat('italic'));
      setIsUnderline(selection.hasFormat('underline'));

      // Update block type
      const anchorNode = selection.anchor.getNode();
      const element =
        anchorNode.getKey() === 'root' ? anchorNode : anchorNode.getTopLevelElementOrThrow();

      const elementType = element.getType();
      if ($isHeadingNode(element)) {
        setBlockType(element.getTag());
      } else if ($isListNode(element)) {
        setBlockType(element.getTag());
      } else {
        setBlockType('paragraph');
      }
    }
  }, []);

  useEffect(() => {
    return mergeRegister(
      editor.registerUpdateListener(({ editorState }) => {
        editorState.read(() => {
          updateToolbar();
        });
      }),
      editor.registerCommand(
        SELECTION_CHANGE_COMMAND,
        () => {
          updateToolbar();
          return false;
        },
        1,
      ),
    );
  }, [editor, updateToolbar]);

  const formatText = (format: 'bold' | 'italic' | 'underline') => {
    editor.dispatchCommand(FORMAT_TEXT_COMMAND, format);
  };

  const formatHeading = (headingSize: HeadingTagType) => {
    if (blockType === headingSize) {
      // Toggle off: convert to paragraph
      editor.update(() => {
        const selection = $getSelection();
        if ($isRangeSelection(selection)) {
          $setBlocksType(selection, () => $createParagraphNode());
        }
      });
    } else {
      editor.update(() => {
        const selection = $getSelection();
        if ($isRangeSelection(selection)) {
          $setBlocksType(selection, () => $createHeadingNode(headingSize));
        }
      });
    }
  };

  const formatList = (listType: 'bullet' | 'number') => {
    if (listType === 'bullet') {
      if (blockType === 'ul') {
        editor.dispatchCommand(REMOVE_LIST_COMMAND, undefined);
      } else {
        editor.dispatchCommand(INSERT_UNORDERED_LIST_COMMAND, undefined);
      }
    } else {
      if (blockType === 'ol') {
        editor.dispatchCommand(REMOVE_LIST_COMMAND, undefined);
      } else {
        editor.dispatchCommand(INSERT_ORDERED_LIST_COMMAND, undefined);
      }
    }
  };

  return (
    <div className="editor-toolbar">
      <button
        type="button"
        className={`toolbar-button ${isBold ? 'active' : ''}`}
        onClick={() => formatText('bold')}
        aria-label="Format Bold"
        title="Bold"
      >
        <TextB size={18} weight="duotone" />
      </button>
      <button
        type="button"
        className={`toolbar-button ${isItalic ? 'active' : ''}`}
        onClick={() => formatText('italic')}
        aria-label="Format Italic"
        title="Italic"
      >
        <TextItalic size={18} weight="duotone" />
      </button>
      <button
        type="button"
        className={`toolbar-button ${isUnderline ? 'active' : ''}`}
        onClick={() => formatText('underline')}
        aria-label="Format Underline"
        title="Underline"
      >
        <TextUnderline size={18} weight="duotone" />
      </button>

      <div className="toolbar-divider" />

      <button
        type="button"
        className={`toolbar-button ${blockType === 'h1' ? 'active' : ''}`}
