/**
 * useAutoSave Hook
 *
 * Custom React hook for debounced auto-saving with state indicators.
 * Prevents excessive save calls by debouncing user input changes.
 */

import debounce from 'lodash.debounce';
import { useCallback, useEffect, useRef, useState } from 'react';

export type SaveState = 'idle' | 'saving' | 'saved' | 'error';

export interface UseAutoSaveOptions<T> {
  /** The content to auto-save */
  content: T;
  /** Callback function to save the content */
  onSave: (content: T) => Promise<void>;
  /** Debounce delay in milliseconds (default: 30000ms = 30 seconds) */
  delay?: number;
  /** Whether auto-save is enabled (default: true) */
  enabled?: boolean;
}

export interface UseAutoSaveReturn {
  /** Current save state */
  saveState: SaveState;
  /** Error message if save failed */
  error: string | null;
  /** Manually trigger a save */
  triggerSave: () => void;
  /** Reset save state and error */
  reset: () => void;
}

/**
 * useAutoSave Hook
 *
 * Automatically saves content after a specified delay of inactivity.
 * Provides save state for UI indicators.
 *
 * @example
 * ```tsx
 * const { saveState } = useAutoSave({
 *   content: editorContent,
 *   onSave: async (content) => {
 *     await invoke('update_snapshot_content', { storyId, content, wordCount });
 *   },
 *   delay: 30000, // 30 seconds
 * });
 * ```
 */
export function useAutoSave<T>({
  content,
  onSave,
  delay = 30000,
  enabled = true,
}: UseAutoSaveOptions<T>): UseAutoSaveReturn {
  const [saveState, setSaveState] = useState<SaveState>('idle');
  const [error, setError] = useState<string | null>(null);

  // Track if this is the first render
  const isFirstRender = useRef(true);

  // Store the latest content to avoid stale closures
  const contentRef = useRef(content);
  contentRef.current = content;

  // Store the latest onSave callback to avoid stale closures and dependency issues
  const onSaveRef = useRef(onSave);
  onSaveRef.current = onSave;

  // Track timeout for cleanup
  const savedTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Save function - uses refs to avoid dependency on onSave
  const performSave = useCallback(
    async (contentToSave: T) => {
      if (!enabled) return;

      setSaveState('saving');
      setError(null);

      try {
        await onSaveRef.current(contentToSave);
        setSaveState('saved');

      // Clear any existing timeout
      if (savedTimeoutRef.current) {
        clearTimeout(savedTimeoutRef.current);
      }

      // Reset to idle after showing "saved" for a moment
      savedTimeoutRef.current = setTimeout(() => {
        setSaveState('idle');
        savedTimeoutRef.current = null;
      }, 2000);
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Save failed';
        setError(errorMessage);
        setSaveState('error');
        console.error('Auto-save error:', err);
      }
    },
    [enabled],
  );

  // Create debounced save function
  const debouncedSave = useRef(
    debounce((callback: () => void) => {
      callback();
    }, delay),
  );

  // Update debounce delay if it changes
  useEffect(() => {
    debouncedSave.current = debounce((callback: () => void) => {
      callback();
    }, delay);

    return () => {
      debouncedSave.current.cancel();
      // Clean up saved timeout on unmount
      if (savedTimeoutRef.current) {
        clearTimeout(savedTimeoutRef.current);
      }
    };
  }, [delay]);

  // Trigger auto-save when content changes
  useEffect(() => {
    // Skip auto-save on first render (initial content load)
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }

    if (!enabled) {
      return;
    }

    // Cancel any pending save and schedule a new one
    debouncedSave.current.cancel();
    debouncedSave.current(() => {
      void performSave(content);
    });

    // Cleanup: cancel pending saves on unmount
    return () => {
      debouncedSave.current.cancel();
    };
  }, [content, enabled, performSave]);

  // Manual save trigger
  const triggerSave = useCallback(() => {
    debouncedSave.current.cancel();
    void performSave(contentRef.current);
  }, [performSave]);

  // Reset function
  const reset = useCallback(() => {
    setSaveState('idle');
    setError(null);
    debouncedSave.current.cancel();
    if (savedTimeoutRef.current) {
      clearTimeout(savedTimeoutRef.current);
      savedTimeoutRef.current = null;
    }
  }, []);

  return {
    saveState,
    error,
    triggerSave,
    reset,
  };
}

